def do_flip(author):
    """
    Given an author import dict, flip its name in place
    i.e. Smith, John => John Smith

    :param dict author:
    :rtype: None
    """
    if 'personal_name' in author and author['personal_name'] != author['name']:
        # Don't flip names if name is more complex than personal_name (legacy behaviour)
        return
    first_comma = author['name'].find(', ')
    if first_comma == -1:
        return
    # e.g: Harper, John Murdoch, 1845-
    if author['name'].find(',', first_comma + 1) != -1:
        return
    if author['name'].find('i.e.') != -1:
        return
    if author['name'].find('i. e.') != -1:
        return
    name = flip_name(author['name'])
    author['name'] = name
    if 'personal_name' in author:
        author['personal_name'] = name


def pick_from_matches(author, match):
    """
    Finds the best match for author from a list of OL authors records, match.

    :param dict author: Author import representation
    :param list match: List of matching OL author records
    :rtype: dict
    :return: A single OL author record from match
    """
    maybe = []
    if 'birth_date' in author and 'death_date' in author:
        maybe = [m for m in match if 'birth_date' in m and 'death_date' in m]
    elif 'date' in author:
        maybe = [m for m in match if 'date' in m]
    if not maybe:
        maybe = match
    if len(maybe) == 1:
        return maybe[0]
    return min(maybe, key=key_int)


def _name_variants(author: dict[str, Any]) -> list[str]:
    name = author['name']
    variants = [name]
    if ', ' in name:
        flipped_name = flip_name(name)
        if flipped_name and flipped_name != name:
            variants.append(flipped_name)
    return variants


def _name_query(field: str, name: str) -> dict[str, Any]:
    query: dict[str, Any] = {"type": "/type/author"}
    # `~` treats `*` as a wildcard. Equality keeps supplied asterisks literal.
    if '*' in name or '_' in name:
        query[field] = name
    else:
        query[f"{field}~"] = name
    return query


def _author_search_stages(
    author: dict[str, Any],
) -> list[list[tuple[dict[str, Any], str, str]]]:
    variants = _name_variants(author)
    stages = [
        [(_name_query('name', name), 'name', name) for name in variants],
        [
            (_name_query('alternate_names', name), 'alternate_name', name)
            for name in variants
        ],
    ]

    birth_year = extract_year(str(author.get('birth_date') or ''))
    death_year = extract_year(str(author.get('death_date') or ''))
    if (
        len(birth_year) == 4
        and birth_year.isdigit()
        and len(death_year) == 4
        and death_year.isdigit()
    ):
        name_tokens = author['name'].split()
        surname = name_tokens[-1] if name_tokens else ''
        # The leading asterisk is intentional for surname suffix matching. A literal
        # asterisk in the surname cannot be represented safely in this query pattern.
        if surname and '*' not in surname:
            stages.append(
                [
                    (
                        {
                            "type": "/type/author",
                            "name~": f"* {surname}",
                            "birth_date~": f"*{birth_year or '-1'}*",
                            "death_date~": f"*{death_year or '-1'}*",
                        },
                        'surname',
                        surname,
                    )
                ]
            )
    return stages


def _get_authors(query: dict[str, Any]) -> list["Author"]:
    def walk_redirects(obj):
        while obj.type.key == '/type/redirect':
            assert obj['location'] != obj['key']
            obj = web.ctx.site.get(obj['location'])
        return obj

    authors = [web.ctx.site.get(key) for key in web.ctx.site.things(query)]
    results = []
    seen = set()
    for author in authors:
        if author is None:
            continue
        author = walk_redirects(author)
        if author['key'] not in seen:
            seen.add(author['key'])
            results.append(author)
    return results


def find_author(author: dict[str, Any]) -> list["Author"]:
    """Search for author candidates in exact, alternate, then surname order."""
    for stage in _author_search_stages(author):
        matches = []
        for query, _kind, _value in stage:
            matches.extend(_get_authors(query))
        if matches:
            deduplicated = {candidate['key']: candidate for candidate in matches}
            return list(deduplicated.values())
    return []


def _date_year(author: dict[str, Any], field: str) -> str:
    value = author.get(field)
    return extract_year(str(value)) if value is not None else ''


def _author_years_match(left: dict[str, Any], right: dict[str, Any]) -> bool:
    """Compare birth/death years when both records provide an extractable year."""
    for field in ('birth_date', 'death_date'):
        left_year = _date_year(left, field)
        right_year = _date_year(right, field)
        if left_year and right_year and left_year != right_year:
            return False
    return True


def _candidate_matches_stage(
    candidate: "Author", author: dict[str, Any], kind: str, value: str
) -> bool:
    if kind == 'name':
        name_matches = candidate.get('name', '').casefold() == value.casefold()
    elif kind == 'alternate_name':
        alternate_names = candidate.get('alternate_names', []) or []
        if isinstance(alternate_names, str):
            alternate_names = [alternate_names]
        name_matches = any(
            alternate.casefold() == value.casefold() for alternate in alternate_names
        )
    else:
        candidate_tokens = candidate.get('name', '').split()
        name_matches = (
            bool(candidate_tokens)
            and candidate_tokens[-1].casefold() == value.casefold()
        )
        name_matches = name_matches and all(
            _date_year(author, field)
            and _date_year(candidate, field) == _date_year(author, field)
            for field in ('birth_date', 'death_date')
        )
    return name_matches and (kind == 'surname' or _author_years_match(author, candidate))


def find_entity(author: dict[str, Any]) -> "Author | None":
    """
    Looks for an existing Author record in OL by name
    and returns it if found.

    :param dict author: Author import dict {"name": "Some One"}
    :return: Existing Author record if found, or None.
    """
    for stage in _author_search_stages(author):
        matches = []
        seen = set()
        for query, kind, value in stage:
            for candidate in _get_authors(query):
                if candidate['key'] in seen:
                    continue
                seen.add(candidate['key'])
                assert candidate.type.key == '/type/author'
                if _candidate_matches_stage(candidate, author, kind, value):
                    matches.append(candidate)
        if matches:
            if len(matches) == 1:
                return matches[0]
            return pick_from_matches(author, matches)
    return None


def remove_author_honorifics(name: str) -> str:
    """Remove leading honorifics while preserving names that are honorifics alone."""
    if _normalize_author_name(name) in _HONORIFIC_EXCEPTIONS_NORMALIZED:
        return name

    original = name
    remaining = name
    while match := _HONORIFIC_PREFIX_RE.match(remaining):
        remaining = remaining[match.end() :]
    if not remaining.strip() or _HONORIFIC_PREFIX_RE.fullmatch(remaining):
        return original
    return remaining


def import_author(author: dict[str, Any], eastern=False) -> "Author | dict[str, Any]":
    """
    Converts an import style new-author dictionary into an
    Open Library existing author, or new author candidate, representation.
    Does NOT create new authors.

    :param dict author: Author import record {"name": "Some One"}
